import {
  parseNodeList,
  type DeployConfig,
  type NodeSpec,
} from "../lib/configSchema";
import type { SshTarget } from "../lib/hostPlanner";

/**
 * PostgreSQL 18 + PgBouncer provisioner.
 *
 * Every builder is pure so the exact configuration can be asserted in tests;
 * `provisionPostgres18` only performs remote work through the supplied runner.
 */

export interface ProvisionRunner {
  dryRun?: boolean;
  run(target: SshTarget, command: string, options?: { sudo?: boolean; sudoUser?: string; cwd?: string; timeoutMs?: number }): unknown;
  capture(target: SshTarget, command: string, options?: { sudo?: boolean; sudoUser?: string; cwd?: string }): string;
  writeRemoteFile(input: { target: SshTarget; path: string; content: string | Buffer; mode?: number; sudo?: boolean }): void;
}

export interface PgNodeRef {
  nodeId?: string;
  sshHost?: string;
  sshPort?: number;
  privateIp: string;
  servicePort?: number;
  port?: number;
  ssh?: SshTarget;
}

export interface PostgresProvisionInput {
  runner: ProvisionRunner;
  config: DeployConfig;
  dryRun?: boolean;
  primary?: PgNodeRef | null;
  replicas?: PgNodeRef[];
}

export interface ProvisionReport {
  commands: string[];
  nodes: string[];
}

const version = (config?: Pick<DeployConfig, "PG_VERSION">): string => config?.PG_VERSION ?? "18";

export const postgresDataDir = (config?: Pick<DeployConfig, "PG_VERSION">): string =>
  `/var/lib/postgresql/${version(config)}/main`;

export const postgresConfigPath = (config?: Pick<DeployConfig, "PG_VERSION">): string =>
  `/etc/postgresql/${version(config)}/main/conf.d/zz-pg-switch.conf`;

const nodeEndpoint = (node: PgNodeRef | string): string =>
  typeof node === "string" ? node : node.privateIp ?? node.sshHost ?? "127.0.0.1";

const nodePort = (node: PgNodeRef | string): number =>
  typeof node === "string" ? 5432 : node.servicePort ?? node.port ?? 5432;

const nodeSsh = (config: DeployConfig, node: PgNodeRef | string): SshTarget => {
  if (typeof node !== "string" && node.ssh) return node.ssh;
  return {
    host: typeof node === "string" ? node : node.sshHost ?? node.privateIp,
    port: typeof node === "string" ? config.PG_SSH_PORT : node.sshPort ?? config.PG_SSH_PORT,
    user: config.PG_SSH_USER,
    keyPath: config.PG_SSH_KEY_PATH ?? "",
    sudoPassword: config.PG_SUDO_PASSWORD,
  };
};

const specToRef = (spec: NodeSpec): PgNodeRef => ({
  nodeId: spec.nodeId,
  sshHost: spec.sshHost,
  sshPort: spec.sshPort,
  privateIp: spec.privateIp,
  servicePort: spec.servicePort,
});

const slotName = (node: PgNodeRef | string, index = 0): string => {
  const raw = typeof node === "string" ? `replica_${index + 1}` : node.nodeId ?? `replica_${index + 1}`;
  return raw.toLowerCase().replace(/[^a-z0-9_]+/g, "_").replace(/^([^a-z])/, "r_$1").slice(0, 63);
};

/** The exact PostgreSQL 18 tuning block from the storage architecture. */
export const postgresConfigSnippet = (_config?: Pick<DeployConfig, "PG_VERSION">): string => `listen_addresses = '*'
max_connections = 300
shared_buffers = 8GB
effective_cache_size = 24GB
work_mem = 32MB
maintenance_work_mem = 1GB
io_method = 'io_uring'
synchronous_commit = on
wal_level = replica
max_wal_senders = 16
max_replication_slots = 16
max_wal_size = 16GB
min_wal_size = 2GB
checkpoint_completion_target = 0.9
random_page_cost = 1.1
shared_preload_libraries = 'pg_stat_statements'
track_io_timing = on
`;

/** Install PostgreSQL 18, contrib extensions and PgBouncer. */
export const bootstrapCommands = (
  config: DeployConfig,
  role: "primary" | "replica" | "pgbouncer" = "primary",
): string[] => [
  "apt-get update",
  `DEBIAN_FRONTEND=noninteractive apt-get install -y postgresql-${version(config)} postgresql-contrib-${version(config)} pgbouncer`,
  "systemctl enable --now postgresql",
  ...(role === "primary" || role === "pgbouncer" ? ["systemctl enable --now pgbouncer"] : []),
  `install -d -m 0700 -o postgres -g postgres ${postgresDataDir(config)}`,
];

/** pg_hba policy: TLS + SCRAM for every application/replication source. */
export const pgHbaSnippet = (config: DeployConfig, allowedSources: string[]): string => {
  const sources = [...new Set(allowedSources.filter((entry) => entry.length > 0))];
  return [
    "local   all             all                                     peer",
    "host    all             all             127.0.0.1/32            scram-sha-256",
    "host    all             all             ::1/128                 scram-sha-256",
    ...sources.flatMap((source) => [
      `hostssl all             all             ${source}/32            scram-sha-256`,
      `hostssl replication     all             ${source}/32            scram-sha-256`,
    ]),
  ].join("\n") + "\n";
};

/** Primary SQL: application role/database, replication role and TLS host rules. */
export const primaryBootstrapSql = (config: DeployConfig, replicas: Array<PgNodeRef | string>): string => {
  const replicaSources = replicas.map((node) => nodeEndpoint(node));
  const allowed = [...replicaSources];
  return [
    `DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = '${config.PG_DB_USER}') THEN CREATE ROLE "${config.PG_DB_USER}" LOGIN PASSWORD '${config.PG_DB_PASSWORD}'; ELSE ALTER ROLE "${config.PG_DB_USER}" PASSWORD '${config.PG_DB_PASSWORD}'; END IF; END $$;`,
    `SELECT 'CREATE DATABASE "${config.PG_DB_NAME}" OWNER "${config.PG_DB_USER}"' WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = '${config.PG_DB_NAME}')\\gexec`,
    `DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = '${config.PG_REPLICATION_USER}') THEN CREATE ROLE "${config.PG_REPLICATION_USER}" WITH REPLICATION LOGIN PASSWORD '${config.PG_REPLICATION_PASSWORD}'; ELSE ALTER ROLE "${config.PG_REPLICATION_USER}" WITH REPLICATION LOGIN PASSWORD '${config.PG_REPLICATION_PASSWORD}'; END IF; END $$;`,
    ...replicas.map((node, index) => {
      const slot = slotName(node, index);
      return `DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_replication_slots WHERE slot_name = '${slot}') THEN PERFORM pg_create_physical_replication_slot('${slot}'); END IF; END $$;`;
    }),
    `-- pg_hba sources: ${allowed.join(",")}`,
  ].join("\n") + "\n";
};

/** Slot creation + `pg_basebackup -R` for each replica (idempotent). */
export const replicaCommands = (
  primary: PgNodeRef | string,
  replica: PgNodeRef | string,
  config?: DeployConfig,
): string[] => {
  const primaryIp = nodeEndpoint(primary);
  const primaryPort = nodePort(primary);
  const dataDir = postgresDataDir(config);
  const user = config?.PG_REPLICATION_USER ?? "pg_replicator";
  return [
    `test -s ${dataDir}/PG_VERSION || pg_basebackup -h ${primaryIp} -p ${primaryPort} -U ${user} -D ${dataDir} -Fp -Xs -P -R`,
    `test -s ${dataDir}/PG_VERSION && echo 'replica already initialized'`,
    "systemctl enable --now postgresql",
  ];
};

/** The exact PgBouncer transaction-pooling configuration. */
export const pgbouncerIni = (config: DeployConfig): string => `[pgbouncer]
listen_port = ${config.PGBOUNCER_PORT}
pool_mode = transaction
max_client_conn = ${config.PGBOUNCER_MAX_CLIENT_CONN}
default_pool_size = ${config.PGBOUNCER_DEFAULT_POOL_SIZE}
reserve_pool_size = 10
max_prepared_statements = ${config.PGBOUNCER_MAX_PREPARED_STATEMENTS}
server_reset_query_always = 0
ignore_startup_parameters = extra_float_digits,search_path
auth_type = scram-sha-256
auth_file = /etc/pgbouncer/userlist.txt
`;

export const pgbouncerUserlist = (config: DeployConfig): string =>
  `"${config.PG_DB_USER}" "${config.PG_DB_PASSWORD}"\n"${config.PG_REPLICATION_USER}" "${config.PG_REPLICATION_PASSWORD}"\n`;

const write = (runner: ProvisionRunner, target: SshTarget, path: string, content: string, mode = 0o600): void => {
  runner.writeRemoteFile({ target, path, content, mode, sudo: true });
};

/**
 * Applies PostgreSQL 18, streaming replicas and PgBouncer. The runner is the
 * only side effect; tests pass a recording fake.
 */
export const provisionPostgres18 = (input: PostgresProvisionInput): ProvisionReport => {
  const { runner, config } = input;
  const commands: string[] = [];
  const nodes: string[] = [];
  const primary = input.primary === undefined
    ? parseNodeList(config.PG_PRIMARY_NODE)[0] ?? null
    : input.primary;
  const replicas = input.replicas ?? parseNodeList(config.PG_REPLICA_NODES).map(specToRef);
  if (!primary) return { commands, nodes };

  const primarySsh = nodeSsh(config, primary);
  const primaryIp = nodeEndpoint(primary);
  nodes.push(primaryIp);
  for (const command of bootstrapCommands(config, "primary")) {
    commands.push(command);
    runner.run(primarySsh, command, { sudo: true });
  }
  const snippet = postgresConfigSnippet(config);
  write(runner, primarySsh, postgresConfigPath(config), snippet, 0o644);
  const replicaRefs = replicas;
  const primaryAllowed = [
    primaryIp,
    ...replicaRefs.map((node) => nodeEndpoint(node)),
    ...parseNodeList(config.CORE_NODES).map((node) => node.privateIp),
    ...(config.CORE_PRIVATE_IP ? [config.CORE_PRIVATE_IP] : []),
  ];
  write(runner, primarySsh, `/etc/postgresql/${version(config)}/main/pg_hba.conf`, pgHbaSnippet(config, primaryAllowed), 0o600);
  const bootstrapSqlPath = `/tmp/pg18-bootstrap-${process.pid}.sql`;
  write(runner, primarySsh, bootstrapSqlPath, primaryBootstrapSql(config, replicaRefs), 0o600);
  const bootstrap = `su - postgres -c "psql -v ON_ERROR_STOP=1 -f ${bootstrapSqlPath}"`;
  commands.push(bootstrap);
  runner.run(primarySsh, bootstrap, { sudo: true });
  runner.run(primarySsh, "systemctl restart postgresql", { sudo: true });

  if (config.PGBOUNCER_ENABLED) {
    write(runner, primarySsh, "/etc/pgbouncer/pgbouncer.ini", pgbouncerIni(config), 0o640);
    write(runner, primarySsh, "/etc/pgbouncer/userlist.txt", pgbouncerUserlist(config), 0o600);
    const restart = "systemctl enable --now pgbouncer && systemctl restart pgbouncer";
    commands.push(restart);
    runner.run(primarySsh, restart, { sudo: true });
  }

  for (const [index, replica] of replicaRefs.entries()) {
    const replicaSsh = nodeSsh(config, replica);
    const replicaIp = nodeEndpoint(replica);
    nodes.push(replicaIp);
    for (const command of bootstrapCommands(config, "replica")) {
      commands.push(command);
      runner.run(replicaSsh, command, { sudo: true });
    }
    write(runner, replicaSsh, postgresConfigPath(config), snippet, 0o644);
    write(runner, replicaSsh, `/etc/postgresql/${version(config)}/main/pg_hba.conf`, pgHbaSnippet(config, [primaryIp]), 0o600);
    for (const command of replicaCommands(primary, replica, config)) {
      commands.push(command);
      runner.run(replicaSsh, command, { sudo: true, sudoUser: "postgres" });
    }
    if (config.PGBOUNCER_ENABLED) {
      write(runner, replicaSsh, "/etc/pgbouncer/pgbouncer.ini", pgbouncerIni(config), 0o640);
      write(runner, replicaSsh, "/etc/pgbouncer/userlist.txt", pgbouncerUserlist(config), 0o600);
      const restart = "systemctl enable --now pgbouncer && systemctl restart pgbouncer";
      commands.push(restart);
      runner.run(replicaSsh, restart, { sudo: true });
    }
    const slot = slotName(replica, index);
    commands.push(`pg_create_physical_replication_slot('${slot}')`);
  }
  return { commands, nodes };
};
import { parseNodeList, type DeployConfig } from "../lib/configSchema";
import type { SshTarget } from "../lib/hostPlanner";
import type { ProvisionReport, ProvisionRunner } from "./postgres18Provisioner";

/**
 * Dedicated append-only audit database and monthly-partitioned operational log
 * database. The DDL is copied verbatim from the storage architecture.
 */

export const AUDIT_DB_DDL = `CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS audit_records (
  seq_no              BIGINT GENERATED ALWAYS AS IDENTITY UNIQUE,
  id                  UUID         PRIMARY KEY,
  created_at          TIMESTAMPTZ  NOT NULL,
  ingested_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
  actor_id            UUID         NOT NULL,
  actor_email         VARCHAR(191) NULL,
  role                VARCHAR(64)  NOT NULL,
  action              VARCHAR(96)  NOT NULL,
  entity_type         VARCHAR(64)  NOT NULL,
  entity_id           VARCHAR(64)  NOT NULL,
  merchant_id         UUID         NULL,
  approval_request_id UUID         NULL,
  request_id          VARCHAR(64)  NULL,
  client_ip           VARCHAR(45)  NULL,
  user_agent          TEXT         NULL,
  before_json         JSONB        NOT NULL,
  after_json          JSONB        NOT NULL,
  prev_hash           CHAR(64)     NOT NULL,
  row_hash            CHAR(64)     NOT NULL
);

CREATE INDEX IF NOT EXISTS audit_records_entity_idx
  ON audit_records (entity_type, entity_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS audit_records_actor_idx
  ON audit_records (actor_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS audit_records_created_brin_idx
  ON audit_records USING brin (created_at);

CREATE INDEX IF NOT EXISTS audit_records_trgm_search_idx
  ON audit_records USING gin (
    action gin_trgm_ops,
    entity_type gin_trgm_ops,
    entity_id gin_trgm_ops,
    actor_email gin_trgm_ops
  );

-- Immutability trigger: forbid UPDATE and DELETE even by table owner unless superuser maintenance
CREATE OR REPLACE FUNCTION forbid_audit_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'AUDIT_TAMPER_PROHIBITED: audit_records is strictly append-only';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_audit_immutable ON audit_records;
CREATE TRIGGER trg_audit_immutable
  BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_records
  FOR EACH STATEMENT EXECUTE FUNCTION forbid_audit_mutation();

-- Least-privilege runtime privileges for pg_audit_writer
REVOKE UPDATE, DELETE, TRUNCATE ON audit_records FROM PUBLIC;
`;

export const LOG_DB_DDL = `CREATE TABLE IF NOT EXISTS attempt_step_logs (
  id                     UUID         NOT NULL,
  attempt_id             UUID         NOT NULL,
  gateway_version_id     UUID         NOT NULL,
  phase                  VARCHAR(32)  NOT NULL,
  step_id                UUID         NULL,
  step_order             INT          NOT NULL,
  redacted_request_json  JSONB        NOT NULL,
  redacted_response_text TEXT         NOT NULL,
  http_status            INT          NULL,
  duration_ms            INT          NULL,
  outcome                VARCHAR(64)  NOT NULL,
  created_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

CREATE INDEX IF NOT EXISTS attempt_step_logs_attempt_idx
  ON attempt_step_logs (attempt_id, step_order ASC);

CREATE INDEX IF NOT EXISTS attempt_step_logs_created_brin_idx
  ON attempt_step_logs USING brin (created_at);

CREATE TABLE IF NOT EXISTS http_access_logs (
  id             BIGINT GENERATED ALWAYS AS IDENTITY,
  request_id     VARCHAR(64)  NOT NULL,
  channel        VARCHAR(24)  NOT NULL,
  method         VARCHAR(10)  NOT NULL,
  route_pattern  VARCHAR(191) NOT NULL,
  status_code    SMALLINT     NOT NULL,
  duration_ms    INT          NOT NULL,
  db_queries     SMALLINT     NOT NULL DEFAULT 0,
  db_duration_ms INT          NOT NULL DEFAULT 0,
  actor_id       UUID         NULL,
  client_ip      VARCHAR(45)  NULL,
  created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

CREATE INDEX IF NOT EXISTS http_access_logs_created_brin_idx
  ON http_access_logs USING brin (created_at);
`;

export const auditDatabaseDdl = (): string => AUDIT_DB_DDL;
export const logDatabaseDdl = (): string => LOG_DB_DDL;
export const auditDbDdl = auditDatabaseDdl;
export const logDbDdl = logDatabaseDdl;

const monthKey = (date: Date): string => `${date.getUTCFullYear()}_${String(date.getUTCMonth() + 1).padStart(2, "0")}`;

const monthStart = (date: Date): string =>
  `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-01`;

const nextMonth = (date: Date): Date => new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1));

/**
 * Creates the next N monthly partitions for both log tables plus the
 * maintenance function/cron SQL. Accepts (monthsAhead, now) or (now, months).
 */
export function ensureLogPartitions(monthsAhead?: number, now?: Date): string;
export function ensureLogPartitions(now?: Date, monthsAhead?: number): string;
export function ensureLogPartitions(first?: number | Date, second?: number | Date): string {
  const monthsAhead = typeof first === "number" ? first : typeof second === "number" ? second : 6;
  const now = first instanceof Date ? first : second instanceof Date ? second : new Date();
  const statements: string[] = [];
  for (let offset = 0; offset < monthsAhead; offset += 1) {
    const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + offset, 1));
    const end = nextMonth(start);
    const suffix = monthKey(start);
    for (const table of ["attempt_step_logs", "http_access_logs"] as const) {
      statements.push(
        `CREATE TABLE IF NOT EXISTS ${table}_${suffix} PARTITION OF ${table} FOR VALUES FROM ('${monthStart(start)}') TO ('${monthStart(end)}');`,
      );
    }
  }
  statements.push(`CREATE OR REPLACE FUNCTION ensure_log_partitions(months_ahead INT DEFAULT 6)
RETURNS void AS $$
DECLARE
  offset INT;
  start_date DATE;
  end_date DATE;
  suffix TEXT;
BEGIN
  FOR offset IN 0..months_ahead - 1 LOOP
    start_date := (date_trunc('month', now())::date + (offset || ' months')::interval)::date;
    end_date := (start_date + interval '1 month')::date;
    suffix := to_char(start_date, 'YYYY_MM');
    EXECUTE format('CREATE TABLE IF NOT EXISTS attempt_step_logs_%s PARTITION OF attempt_step_logs FOR VALUES FROM (%L) TO (%L)', suffix, start_date, end_date);
    EXECUTE format('CREATE TABLE IF NOT EXISTS http_access_logs_%s PARTITION OF http_access_logs FOR VALUES FROM (%L) TO (%L)', suffix, start_date, end_date);
  END LOOP;
END;
$$ LANGUAGE plpgsql;

SELECT ensure_log_partitions(${monthsAhead});
`);
  return statements.join("\n");
}

export const LOG_PARTITION_MAINTENANCE_CRON = "15 1 * * *";
export const logPartitionCronLine = (config: DeployConfig): string =>
  `${LOG_PARTITION_MAINTENANCE_CRON} root su - postgres -c "psql -d ${config.LOG_DB_NAME} -c 'SELECT ensure_log_partitions(6)'" >/var/log/pg-log-partitions.log 2>&1`;

const nodeSsh = (config: DeployConfig, spec: { sshHost: string; sshPort: number }, kind: "audit" | "log"): SshTarget => ({
  host: spec.sshHost,
  port: spec.sshPort,
  user: kind === "audit" ? config.AUDIT_DB_SSH_USER : config.LOG_DB_SSH_USER,
  keyPath: (kind === "audit" ? config.AUDIT_DB_SSH_KEY_PATH : config.LOG_DB_SSH_KEY_PATH) ?? "",
  sudoPassword: kind === "audit" ? config.AUDIT_DB_SUDO_PASSWORD : config.LOG_DB_SUDO_PASSWORD,
});

const repositorySql = (config: DeployConfig, kind: "audit" | "log"): string => {
  const name = kind === "audit" ? config.AUDIT_DB_NAME : config.LOG_DB_NAME;
  const user = kind === "audit" ? config.AUDIT_DB_USER : config.LOG_DB_USER;
  const password = kind === "audit" ? config.AUDIT_DB_PASSWORD : config.LOG_DB_PASSWORD;
  return [
    `DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = '${user}') THEN CREATE ROLE "${user}" LOGIN PASSWORD '${password}'; ELSE ALTER ROLE "${user}" PASSWORD '${password}'; END IF; END $$;`,
    `SELECT 'CREATE DATABASE "${name}" OWNER "${user}"' WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = '${name}')\\gexec`,
  ].join("\n") + "\n";
};

const applySql = (
  runner: ProvisionRunner,
  ssh: SshTarget,
  path: string,
  sql: string,
  config: DeployConfig,
  database: string,
): void => {
  runner.writeRemoteFile({ target: ssh, path, content: sql, mode: 0o600, sudo: true });
  runner.run(ssh, `su - postgres -c "psql -v ON_ERROR_STOP=1 -d ${database} -f ${path}"`, { sudo: true });
};

export interface AuditLogProvisionInput {
  runner: ProvisionRunner;
  config: DeployConfig;
  dryRun?: boolean;
  now?: Date;
}

export const provisionAuditAndLogDb = (input: AuditLogProvisionInput): ProvisionReport => {
  const { runner, config } = input;
  const commands: string[] = [];
  const nodes: string[] = [];
  const install = [
    "apt-get update",
    `DEBIAN_FRONTEND=noninteractive apt-get install -y postgresql-${config.PG_VERSION} postgresql-contrib-${config.PG_VERSION}`,
    "systemctl enable --now postgresql",
  ];
  const auditSpec = parseNodeList(config.AUDIT_DB_NODE)[0];
  if (auditSpec && config.AUDIT_DB_MANAGE_VIA_SSH) {
    const ssh = nodeSsh(config, auditSpec, "audit");
    nodes.push(auditSpec.privateIp);
    for (const command of install) {
      commands.push(command);
      runner.run(ssh, command, { sudo: true });
    }
    const repoPath = `/tmp/pg-audit-bootstrap-${process.pid}.sql`;
    applySql(runner, ssh, repoPath, repositorySql(config, "audit"), config, "postgres");
    const ddlPath = `/tmp/pg-audit-ddl-${process.pid}.sql`;
    applySql(runner, ssh, ddlPath, AUDIT_DB_DDL, config, config.AUDIT_DB_NAME);
    commands.push("apply audit_records DDL + immutability trigger");
  }
  const logSpec = parseNodeList(config.LOG_DB_NODE)[0];
  if (logSpec && config.LOG_DB_MANAGE_VIA_SSH) {
    const ssh = nodeSsh(config, logSpec, "log");
    nodes.push(logSpec.privateIp);
    for (const command of install) {
      commands.push(command);
      runner.run(ssh, command, { sudo: true });
    }
    const repoPath = `/tmp/pg-log-bootstrap-${process.pid}.sql`;
    applySql(runner, ssh, repoPath, repositorySql(config, "log"), config, "postgres");
    const ddlPath = `/tmp/pg-log-ddl-${process.pid}.sql`;
    applySql(runner, ssh, ddlPath, `${LOG_DB_DDL}\n${ensureLogPartitions(input.now ?? new Date(), 6)}`, config, config.LOG_DB_NAME);
    const cronPath = "/etc/cron.d/pg-log-partitions";
    runner.writeRemoteFile({ target: ssh, path: cronPath, content: `${logPartitionCronLine(config)}\n`, mode: 0o644, sudo: true });
    commands.push(`install ${cronPath}`);
  }
  return { commands, nodes };
};
import { parseNodeList, type DeployConfig } from "../lib/configSchema";
import type { SshTarget } from "../lib/hostPlanner";
import type { ProvisionReport, ProvisionRunner } from "./postgres18Provisioner";

export interface RedisProvisionInput {
  runner: ProvisionRunner;
  config: DeployConfig;
  dryRun?: boolean;
}

const nodeSsh = (config: DeployConfig, spec: { sshHost: string; sshPort: number }): SshTarget => ({
  host: spec.sshHost,
  port: spec.sshPort,
  user: config.REDIS_SSH_USER,
  keyPath: config.REDIS_SSH_KEY_PATH ?? "",
  sudoPassword: config.REDIS_SUDO_PASSWORD,
});

/** Bind strictly to the private LAN address and require a password. */
export const redisConfigSnippet = (config: DeployConfig, privateIp: string, port = 6379): string => `bind ${privateIp} 127.0.0.1
protected-mode yes
port ${port}
requirepass ${config.REDIS_PASSWORD}
save 3600 1
maxmemory ${config.REDIS_MAXMEMORY}
maxmemory-policy allkeys-lru
appendonly no
daemonize yes
`;

export const redisFirewallCommands = (config: DeployConfig, port = 6379): string[] => {
  const sources = [
    ...parseNodeList(config.CORE_NODES).map((node) => node.privateIp),
    ...(config.CORE_PRIVATE_IP ? [config.CORE_PRIVATE_IP] : []),
    ...(parseNodeList(config.BACKUP_NODE)[0]?.privateIp ? [parseNodeList(config.BACKUP_NODE)[0]!.privateIp] : []),
  ];
  return [...new Set(sources)].map((source) =>
    `ufw allow from ${source} to any port ${port} proto tcp comment 'Redis from core/backup'`,
  );
};

export const provisionRedis = (input: RedisProvisionInput): ProvisionReport => {
  const { runner, config } = input;
  const commands: string[] = [];
  const nodes: string[] = [];
  for (const spec of parseNodeList(config.REDIS_NODES)) {
    const ssh = nodeSsh(config, spec);
    nodes.push(spec.privateIp);
    for (const command of [
      "apt-get update",
      "DEBIAN_FRONTEND=noninteractive apt-get install -y redis-server",
      "systemctl enable --now redis-server",
    ]) {
      commands.push(command);
      runner.run(ssh, command, { sudo: true });
    }
    const snippet = redisConfigSnippet(config, spec.privateIp, spec.servicePort);
    runner.writeRemoteFile({
      target: ssh,
      path: "/etc/redis/redis.conf.d/zz-pg-switch.conf",
      content: snippet,
      mode: 0o640,
      sudo: true,
    });
    // Debian's redis.conf includes /etc/redis/redis.conf.d only on newer builds;
    // write the effective file too so the bind/requirepass always apply.
    runner.writeRemoteFile({
      target: ssh,
      path: "/etc/redis/redis.conf",
      content: snippet,
      mode: 0o640,
      sudo: true,
    });
    for (const command of redisFirewallCommands(config, spec.servicePort)) {
      commands.push(command);
      runner.run(ssh, command, { sudo: true });
    }
    const restart = "systemctl restart redis-server && redis-cli PING";
    commands.push(restart);
    runner.run(ssh, restart, { sudo: true });
  }
  return { commands, nodes };
};

