import { describe, expect, test } from "bun:test";
import { loadDeployConfig } from "../lib/configSchema";
import type { SshTarget } from "../lib/hostPlanner";
import type { ProvisionRunner } from "../provisioners/postgres18Provisioner";
import {
  bootstrapCommands,
