 const buildRailSummary = async () => {
   const [total, blocked, modeRows, routeHealthRows] = await Promise.all([
     client.rail.count(),
     client.rail.count({ where: { blocked: true } }),
     client.rail.groupBy({ by: ["collectionMode"], _count: { _all: true } }),
