     total,
     active: total - blocked,
     blocked,
     byMode,
     routes: {
       healthy: routeHealth.HEALTHY ?? 0,
       degraded: routeHealth.DEGRADED ?? 0,
       openBreaker: routeHealth.OPEN_BREAKER ?? 0,
     },
   };
 };

