   const effectiveTo = body.effectiveTo ? new Date(body.effectiveTo) : now;
   if (Number.isNaN(effectiveTo.getTime())) {
     throw new ApiError(400, "INVALID_EFFECTIVE_TO", "effectiveTo must be a valid date");
   }
