   private phaseStatus(phase: FlowPhase, hasSteps: boolean): AdapterAttemptStatus {
     if (!hasSteps) {
       return phase === "SUBMIT" ? "SUCCEEDED" : "AWAITING_CUSTOMER";
     }
     return "SUCCEEDED";
   }

