 export const normalizeApprovalSubjectType = (value: string | null | undefined): string => {
   const normalized = String(value ?? "")
     .trim()
     .replace(/[\s-]+/g, "_")
     .toUpperCase();
   return APPROVAL_SUBJECT_TYPE_ALIASES[normalized.replaceAll("_", "")] ?? normalized;
