+// ---------------------------------------------------------------------------
+// Types
+// ---------------------------------------------------------------------------
+
+type LogType = "info" | "warn" | "error";
+
+interface LogEntry {
+    content: string;
+    type: LogType;
+    at: number; // ms since request start
+}
+
+export interface RequestLogger {
+    log: (msg: string) => void;
+    warn: (msg: string) => void;
+    error: (msg: string) => void;
+    end: () => void;
