+    const backupHost = plan.hosts.find((host) => host.roles.includes("backup"));
+    if (backupHost) {
+      deployBackupDaemon({ runner, config, host: backupHost });
+    } else {
+      warn("BACKUP_ENABLED but the plan has no backup host; the daemon was not deployed");
+    }
   }

