 const signLeaf = (input: {
   run: (command: string, args: string[], cwd: string) => void;
   directory: string;
   material: CertMaterial;
   ou: string;
   sans: string[];
   extendedKeyUsage: "serverAuth" | "clientAuth" | "serverAuth,clientAuth";
   validityDays: number;
