     "x509", "-req", "-in", csr,
     "-CA", "internal-ca.crt", "-CAkey", "internal-ca.key", "-CAcreateserial",
     "-out", `${baseName}.crt`, "-days", String(input.validityDays),
     "-extfile", ext, "-extensions", "v3",
