      enabled: this.enabled,
      nextFullAt: this.next.full?.toISOString() ?? null,
      nextDeltaAt: this.next.delta?.toISOString() ?? null,
      nextDrillAt: this.next.drill?.toISOString() ?? null,
    };
  }

