      task = this
        .runJob(job, slotAt)
        .catch((error) => {
          this.logger.error(`[pg-backup-daemon] ${job} job failed: ${this.safeMessage(error)}`);
        })
        .finally(() => {
          this.running.delete(job);
          this.pending.delete(task);
        });
      this.pending.add(task);
      started.push(task);
    }

    await Promise.all(started);
