interface UniqueConstraint {
  model: string;
  table: string;
  fields: string[];
  dbColumns: string[];
  kind: "primary" | "unique";
  label: string;
}

const uniqueConstraints: UniqueConstraint[] = [];
for (const model of schema.models) {
  // A single journal line is deliberately unbalanced; the schema suite keeps
  // the shared test database invariant-neutral so parallel exhaustive files
  // can verify the continuous drift at any instant.
  if (model.tableName === "journal_lines") {
    continue;
  }
  // The outbox uses an auto-increment primary key that the storage-engine and
  // performance suites also drive concurrently. Colliding with a serial key
  // would test sequence allocation, not a semantic unique constraint, so the
  // outbox is covered by the index inventory instead.
  if (model.tableName === "outbox_events") {
    continue;
  }
  for (const fields of model.idBlocks) {
    uniqueConstraints.push({
      model: model.name,
      table: model.tableName,
      fields,
      dbColumns: fields.map((field) => dbColumnFor(model.tableName, field)),
      kind: "primary",
      label: `${model.tableName}(${fields.join(",")})`,
    });
  }
  for (const fields of model.uniqueBlocks) {
    uniqueConstraints.push({
      model: model.name,
      table: model.tableName,
      fields,
      dbColumns: fields.map((field) => dbColumnFor(model.tableName, field)),
      kind: "unique",
      label: `${model.tableName}(${fields.join(",")})`,
    });
  }
  for (const field of model.fields) {
    if (field.isRelation || field.isList) {
      continue;
    }
    if (field.isId || field.isUnique) {
      uniqueConstraints.push({
        model: model.name,
        table: model.tableName,
        fields: [field.name],
        dbColumns: [field.dbName],
        kind: field.isId ? "primary" : "unique",
        label: `${model.tableName}(${field.name})`,
      });
    }
  }
}

