     log(`  Redis nodes: ${report.nodes.join(", ") || "none"}`);
   }
   if ((config.AUDIT_DB_MANAGE_VIA_SSH || config.LOG_DB_MANAGE_VIA_SSH) && shouldRunStorage(options, ["audit-db", "log-db"])) {
