             border: `1px solid ${palette.border}`,
             fontSize: "12px",
             fontWeight: 500,
             lineHeight: 1,
             whiteSpace: "nowrap",
             userSelect: "none",
           }}
         >
           {props.showDot && (
             <span
               style={{
                 width: "6px",
                 height: "6px",
                 borderRadius: "9999px",
                 backgroundColor: palette.dot,
                 flexShrink: 0,
               }}
             />
           )}
           <span>{displayLabel}</span>
         </span>
       );
     };
   },
 });
