       return stream;
     } catch (error) {
       markNodeFailure(node);
       lastError = error;
     }
   }
   if (lastStream) return lastStream;
   if (lastError !== undefined) {
     if (!hasSelectableNode(new Set())) throw coreUnavailable();
     throw mapCoreTransportError(lastError);
   }
   throw coreUnavailable();
 };

