       futureEffective: current.filter((row) => row.effectiveFrom.getTime() > now.getTime()).length,
       updatedLast24h: current.filter((row) => now.getTime() - row.updatedAt.getTime() <= 24 * 60 * 60 * 1000).length,
     },
   };
 };

