   const attempt = await client.paymentAttempt.findFirst({
     where: { id: attemptId, linkId: link.id },
   });
   if (!attempt) {
     throw new ApiError(404, "PAYMENT_ATTEMPT_NOT_FOUND", "The payment attempt does not exist");
   }
   return { link, attempt };
 };

