 export interface InvalidationBusOptions {
   namespace?: string;
   publisher?: RedisCompatiblePublisher;
   subscriber?: RedisCompatibleSubscriber;
   /** Maximum number of remembered event ids used for cross-node de-duplication. */
   seenLimit?: number;
