     ssh,
     hostKey: sshKey(ssh),
   };
 };

 const parseSingleNode = (value: string, label: string): NodeSpec | null => {
   const nodes = parseNodeList(value);
   if (nodes.length > 1) throw new Error(`${label} must describe exactly one node`);
   return nodes[0] ?? null;
 };

