 export const archiveCommand = (config: DeployConfig, target: BackupTarget | string = "postgres_core"): string => {
   if (config.BACKUP_ENGINE_MODE === "barman") {
     const backupIp = backupSpec(config)?.privateIp ?? "backup-1";
