+const gate2 = (ctx: GateContext): Promise<GateResult> => result(2, "Storage routing and LSN read-your-own-writes", async () => [
+  ...(await replicaRoutingCheck(ctx)),
+  ...(await ryowCheck(ctx)),
+]);
