+  const out = execFileSync("ip", ["-4", "route", "get", targetIp], { encoding: "utf8" });
+  const match = /src\s+(\d+\.\d+\.\d+\.\d+)/.exec(out);
+  if (!match?.[1]) {
+    throw new Error(`Could not determine local LAN IP toward ${targetIp}: ${out}`);
+  }
