export function discoverHostALanIp(targetIp = '10.209.250.205'): string {
  const out = execSync(`ip -4 route get ${targetIp}`, { encoding: 'utf8' });
  const match = /src\s+(\d+\.\d+\.\d+\.\d+)/.exec(out);
  if (!match?.[1]) {
