export type CertBundle = "core-server" | "admin-client" | "merchant-client" | "checkout-client" | "fake-rails-server" | "backup-server" | "pg-client" | "redis-client" | "audit-db-client" | "log-db-client";

export interface SshTarget {
  host: string;
  port: number;
  user: string;
  keyPath: string;
  sudoPassword: string;
}

export interface ServicePlan {
  name: ServiceName;
  role: DeployRole;
  sourceDir: string;
  remoteDir: string;
  port: number;
  env: Record<string, string>;
  nodeId?: string;
  privateIp?: string;
}

export interface NginxPlan {
  site: NginxSiteName;
  role: DeployRole;
  template: string;
  listenPort: number;
  httpPort: number;
  httpsPort: number;
  ssl: boolean;
  serverName: string;
  sslMode: "lan" | "certbot" | "custom" | "self_signed";
  certPath?: string;
  keyPath?: string;
  staticRoot: string;
}

export interface FirewallRulePlan {
  port: number;
  proto: "tcp";
  fromCidrs?: string[];
  comment: string;
}

export type ComputeNodeRole = "core" | "admin" | "merchant" | "checkout";

export interface NodePlan {
  nodeId: string;
  id: string;
  role: ComputeNodeRole;
  ssh: SshTarget;
  host: string;
  privateIp: string;
  port: number;
  servicePort: number;
  serviceName: ServiceName;
  hostKey: string;
}

export interface StorageNodePlan {
  role: StorageRole;
  nodeId: string;
  sshHost: string;
  sshPort: number;
  privateIp: string;
  servicePort: number;
  port: number;
  ssh: SshTarget;
  hostKey: string;
}

export interface PostgresStoragePlan {
  primary: StorageNodePlan | null;
  replicas: StorageNodePlan[];
  pgbouncer: StorageNodePlan[];
  version: string;
}

export interface StoragePlan {
  nodes: StorageNodePlan[];
  postgres: PostgresStoragePlan;
  redis: StorageNodePlan[];
  auditDb: StorageNodePlan | null;
  logDb: StorageNodePlan | null;
  backup: StorageNodePlan | null;
  "pg-primary": StorageNodePlan | null;
  "pg-replica": StorageNodePlan[];
  pgbouncer: StorageNodePlan[];
  "audit-db": StorageNodePlan | null;
  "log-db": StorageNodePlan | null;
}

export interface BackupPlan {
  enabled: boolean;
  node: StorageNodePlan | null;
  engineMode: DeployConfig["BACKUP_ENGINE_MODE"];
  daemonPort: number;
  s3Bucket: string;
  secondaryTarget: string;
}

export interface HostPlan {
  key: string;
  displayName: string;
  ssh: SshTarget;
  roles: HostRole[];
  services: ServicePlan[];
  nginx: NginxPlan[];
  certs: CertBundle[];
  firewall: FirewallRulePlan[];
  keepReleases: number;
  deployOrder: number;
}

export interface DeployPlan {
  topology: "single-host" | "split" | "distributed";
  hosts: HostPlan[];
  roles: Record<DeployRole, string>;
  database: {
    engine: DeployConfig["DB_ENGINE"];
    host: string;
    port: number;
    name: string;
    user: string;
    privateIp: string | null;
    managedViaSsh: boolean;
  };
  nodes: {
    core: NodePlan[];
    admin: NodePlan[];
    merchant: NodePlan[];
    checkout: NodePlan[];
  };
  storage: StoragePlan;
  replicas: StorageNodePlan[];
  backup: BackupPlan;
}

