    "localhost",
    ...config.FAKE_RAILS_ALLOWED_HOSTS.split(",").map((entry) => entry.trim()),
  ].filter((entry) => entry.length > 0 && entry !== "_"))];

const fakeRailsEnv = (config: DeployConfig): Record<string, string> => ({
