  const logDb = logSpec ? storageNode({ config, role: "log-db", spec: logSpec, user: config.LOG_DB_SSH_USER, keyPath: config.LOG_DB_SSH_KEY_PATH, sudoPassword: config.LOG_DB_SUDO_PASSWORD }) : null;
