RETURNS void AS $$
DECLARE
  offset INT;
  start_date DATE;
  end_date DATE;
  suffix TEXT;
  cutoff_date DATE;
  partition_name TEXT;
  partition_start DATE;
BEGIN
  FOR offset IN 0..months_ahead - 1 LOOP
    start_date := (date_trunc('month', now())::date + (offset || ' months')::interval)::date;
    end_date := (start_date + interval '1 month')::date;
    suffix := to_char(start_date, 'YYYY_MM');
