    BACKUP_SCRATCH_DIR: config.BACKUP_SCRATCH_DIR,
    BACKUP_SCRATCH_AUDIT_DIR:
      config.BACKUP_SCRATCH_AUDIT_DIR.trim() || `${config.BACKUP_SCRATCH_DIR}/audit`,
    BACKUP_SCRATCH_PORT: String(config.BACKUP_SCRATCH_PORT),
