    WALG_BIN: config.BACKUP_WALG_BIN,
    BARMAN_BIN: config.BACKUP_BARMAN_BIN,
    BARMAN_CLOUD_BIN: config.BACKUP_BARMAN_CLOUD_BIN,
    REDIS_CLI_BIN: config.BACKUP_REDIS_CLI_BIN,
