import type { DeployConfig } from "./configSchema";
import type { FirewallRulePlan, HostPlan } from "./hostPlanner";
import type { SshRunner } from "./sshRunner";
import { detectHostOs, installPackageCommand } from "./osDetector";

/**
 * Host-aware UFW provisioning.
 *
 * The rules are derived from the plan (never hand-written per host), so a
 * 1-host staging box and a 5-host production cluster get the same policy. The
 * `ufw` calls are idempotent: a duplicate `ufw allow` is a no-op.
 */

export interface FirewallCommand {
  args: string[];
  description: string;
}

/** Turns one rule into the exact `ufw` invocations. */
export const ufwCommandsForRule = (rule: FirewallRulePlan): FirewallCommand[] => {
  if (!rule.fromCidrs || rule.fromCidrs.length === 0) {
    return [
      {
        args: ["allow", `${rule.port}/tcp`, "comment", rule.comment],
        description: `allow ${rule.port}/tcp from anywhere (${rule.comment})`,
      },
    ];
  }
  return rule.fromCidrs.map((cidr) => ({
    args: ["allow", "from", cidr, "to", "any", "port", String(rule.port), "proto", "tcp", "comment", rule.comment],
    description: `allow ${rule.port}/tcp from ${cidr} (${rule.comment})`,
  }));
};

/**
 * The base policy every host gets before its role rules. The default deny is
 * what makes the role rules meaningful: a port that is not explicitly allowed
 * is closed.
 */
export const baseUfwCommands = (): FirewallCommand[] => [
  { args: ["default", "deny", "incoming"], description: "deny all inbound by default" },
  { args: ["default", "allow", "outgoing"], description: "allow outbound" },
  { args: ["default", "deny", "routed"], description: "deny routed traffic" },
];

export interface FirewallPlan {
  hostKey: string;
  commands: FirewallCommand[];
}

/** Builds the complete ordered command list for one host. */
export const buildFirewallPlan = (host: HostPlan): FirewallPlan => {
  const commands = [...baseUfwCommands()];
  for (const rule of host.firewall) {
    commands.push(...ufwCommandsForRule(rule));
  }
  // Enable last, so a failed rule never leaves the host unreachable.
  commands.push({ args: ["--force", "enable"], description: "enable ufw" });
  return { hostKey: host.key, commands };
};

export interface ApplyFirewallOptions {
  runner: SshRunner;
  host: HostPlan;
  config: DeployConfig;
  dryRun?: boolean;
  logger?: (message: string) => void;
}

/**
 * Applies the firewall to one host.
 *
 * It refuses to run before SSH is proven reachable: enabling ufw on a host
 * where the SSH port is not allowed would lock the operator out. The SSH rule
 * is therefore always emitted first.
 */
export const applyFirewall = (options: ApplyFirewallOptions): FirewallPlan => {
  const plan = buildFirewallPlan(options.host);
  const sshRule = options.host.firewall.find((rule) => rule.port === options.host.ssh.port);
  if (!sshRule) {
    throw new Error(`Refusing to enable ufw on ${options.host.ssh.host}: no SSH rule (port ${options.host.ssh.port}) is planned`);
  }
  if (options.dryRun) {
    for (const command of plan.commands) {
      options.runner.run(options.host.ssh, `ufw ${command.args.map(quote).join(" ")}`, { sudo: true });
    }
    return plan;
  }
  // ufw may be absent on a minimal image; install it with the host's own
  // package manager (Debian/Ubuntu or Arch Linux).
  const hasUfw = options.runner.capture(options.host.ssh, "command -v ufw || true").trim().length > 0;
  if (!hasUfw) {
    const os = detectHostOs(options.runner, options.host);
    const install = installPackageCommand(os, "ufw");
    if (install) {
      try {
        options.runner.run(options.host.ssh, install, { sudo: true });
      } catch (error) {
        options.logger?.(`  ! unable to install ufw on ${options.host.ssh.host}: ${(error as Error).message}`);
      }
    }
  }
  const ufwAvailable = options.runner.capture(options.host.ssh, "command -v ufw || true").trim().length > 0;
  if (!ufwAvailable) {
    options.logger?.(`  ! ufw is unavailable on ${options.host.ssh.host}; skipping firewall rules (local/dev host)`);
    return plan;
  }
  for (const command of plan.commands) {
    options.runner.run(options.host.ssh, `ufw ${command.args.map(quote).join(" ")}`, { sudo: true });
  }
  return plan;
};

/** Reads back the active rules so the deployment audit can print them. */
export const readFirewallStatus = (runner: SshRunner, host: HostPlan): string =>
  runner.capture(host.ssh, "ufw status verbose", { sudo: true });

const quote = (value: string): string =>
  /^[A-Za-z0-9_./:@-]+$/.test(value) ? value : `'${value.replace(/'/g, `'\\''`)}'`;
import { execFileSync } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import {
  auditDbConfigured,
  backupStorageConfigured,
  logDbConfigured,
  parseNodeList,
  pgStorageConfigured,
  redisStorageConfigured,
  type DeployConfig,
  type HostRole,
} from "./configSchema";

/**
 * The mTLS PKI.
 *
 * The internal CA is created offline and its private key never leaves the
 * deployment workstation. Each leaf certificate is bound to the identity the
 * design requires:
 *
 *   - the core server certificate carries `IP:<CORE_PRIVATE_IP>` in its SAN,
 *     because the edge servers reach it by private IP and TLS 1.3 verifies the
 *     hostname;
 *   - each edge client certificate carries the exact `CN=admin-back`,
 *     `CN=merchant-back` or `CN=checkout-back` that `core-back`'s
 *     channel-bound CN guard checks.
 */

export interface CertMaterial {
  name: string;
  certPath: string;
  keyPath: string;
  /** Only the core certificate is a server certificate. */
  kind: "ca" | "server" | "client";
  cn: string;
  sans?: string[];
}

export interface PkiBundle {
  directory: string;
  ca: CertMaterial;
  server: CertMaterial;
  /** The Fake Rails Nginx server certificate (CA-signed, SAN-bound). */
  fakeRails: CertMaterial;
  /** The pg-backup-daemon mTLS server certificate. */
  backup: CertMaterial;
  clients: CertMaterial[];
  /** Optional client certificates for storage/backup mTLS links. */
  storageClients: CertMaterial[];
}

export interface PkiOptions {
  config: DeployConfig;
  /** Defaults to `deploy/.certs`. */
  directory?: string;
  /** Force a regeneration even when the material already exists. */
  rotate?: boolean;
  /** Print the openssl commands instead of running them. */
  dryRun?: boolean;
  /** Overridable for tests. */
  run?: (command: string, args: string[], cwd: string) => void;
}

const DEFAULT_PKI_DIR = resolve(import.meta.dirname, "..", ".certs");

const runOpenssl = (command: string, args: string[], cwd: string): void => {
  execFileSync(command, args, { cwd, stdio: "ignore" });
};

const ensureDirectory = (directory: string): void => {
  mkdirSync(directory, { recursive: true, mode: 0o700 });
  chmodSync(directory, 0o700);
};

const opensslConfig = (options: {
  cn: string;
  ou: string;
  sans: string[];
  extendedKeyUsage: "serverAuth" | "clientAuth" | "serverAuth,clientAuth";
}): string => {
  const san = options.sans.length > 0
    ? `subjectAltName = ${options.sans.join(", ")}`
    : "";
  return `[req]
distinguished_name = dn
prompt = no
[dn]
CN = ${options.cn}
OU = ${options.ou}
O = Payment Gateway
[v3]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature,keyEncipherment
extendedKeyUsage = ${options.extendedKeyUsage}
${san}
`;
};

/**
 * Builds (or verifies) the internal CA and the four leaf certificates.
 *
 * Idempotent: an existing bundle is reused unless `rotate` is set, so a normal
 * deploy never rotates the production certificates by accident.
 */
export const buildPki = (options: PkiOptions): PkiBundle => {
  const directory = options.directory ?? DEFAULT_PKI_DIR;
  const config = options.config;
  const run = options.run ?? runOpenssl;
  const dryRun = options.dryRun === true;
  const rotate = options.rotate === true || config.ROTATE_MTLS_CERTS;

  const caCert = join(directory, "internal-ca.crt");
  const caKey = join(directory, "internal-ca.key");
  const caMaterial: CertMaterial = {
    name: "internal-ca",
    certPath: caCert,
    keyPath: caKey,
    kind: "ca",
    cn: "Payment Gateway Internal CA",
  };

  // The SAN must carry every core private IP: the edge hosts reach the core
  // nodes by IP and TLS 1.3 verifies the hostname.
  const coreNodeIps = parseNodeList(config.CORE_NODES).map((node) => node.privateIp);
  const coreIps = [...new Set(coreNodeIps.length > 0
    ? coreNodeIps
    : (config.CORE_PRIVATE_IP ? [config.CORE_PRIVATE_IP] : []))];
  const serverSans = [
    ...coreIps.map((ip) => `IP:${ip}`),
    "IP:127.0.0.1",
    "DNS:core-back.internal",
  ];
  const server: CertMaterial = {
    name: "core-back",
    certPath: join(directory, "core-back.crt"),
    keyPath: join(directory, "core-back.key"),
    kind: "server",
    cn: "core-back.internal",
    sans: serverSans,
  };
  const clients: CertMaterial[] = [
    { name: "admin-back-client", certPath: join(directory, "admin-back-client.crt"), keyPath: join(directory, "admin-back-client.key"), kind: "client", cn: "admin-back" },
    { name: "merchant-back-client", certPath: join(directory, "merchant-back-client.crt"), keyPath: join(directory, "merchant-back-client.key"), kind: "client", cn: "merchant-back" },
    { name: "checkout-back-client", certPath: join(directory, "checkout-back-client.crt"), keyPath: join(directory, "checkout-back-client.key"), kind: "client", cn: "checkout-back" },
  ];
  const backupIp = parseNodeList(config.BACKUP_NODE)[0]?.privateIp;
  const backup: CertMaterial = {
    name: "backup-daemon",
    certPath: join(directory, "backup-daemon.crt"),
    keyPath: join(directory, "backup-daemon.key"),
    kind: "server",
    cn: "backup-daemon.internal",
    sans: [
      ...(backupIp ? [`IP:${backupIp}`] : []),
      "IP:127.0.0.1",
      "DNS:backup-daemon.internal",
    ],
  };
  const storageClients: CertMaterial[] = [];
  for (const [name, enabled] of [
    ["pg-client", pgStorageConfigured(config)],
    ["redis-client", redisStorageConfigured(config)],
    ["audit-db-client", auditDbConfigured(config)],
    ["log-db-client", logDbConfigured(config)],
  ] as const) {
    if (!enabled) continue;
    storageClients.push({
      name,
      certPath: join(directory, `${name}.crt`),
      keyPath: join(directory, `${name}.key`),
      kind: "client",
      cn: name,
    });
  }
  if (backupStorageConfigured(config) && !storageClients.some((client) => client.name === "backup-client")) {
    storageClients.push({
      name: "backup-client",
      certPath: join(directory, "backup-client.crt"),
      keyPath: join(directory, "backup-client.key"),
      kind: "client",
      cn: "backup-client",
    });
  }

  const fakeRails: CertMaterial = {
    name: "fake-rails",
    certPath: join(directory, "fake-rails.crt"),
    keyPath: join(directory, "fake-rails.key"),
    kind: "server",
    cn: config.FAKE_RAILS_DOMAIN === "_" ? "fakerails.internal" : config.FAKE_RAILS_DOMAIN,
    sans: [
      `DNS:${config.FAKE_RAILS_DOMAIN === "_" ? "fakerails.internal" : config.FAKE_RAILS_DOMAIN}`,
      ...(config.FAKE_RAILS_PRIVATE_IP ? [`IP:${config.FAKE_RAILS_PRIVATE_IP}`] : []),
