 */
export const readThroughReplicaOrPrimary = async <T>(
  primary: PrismaClient,
  minLsnHeader: string | undefined,
  fn: (reader: PrismaClient) => Promise<T>,
  timeoutMs = 3_000,
): Promise<T> => {
  const engine = engineSingleton;
  if (!engine) {
    return fn(primary);
