  const consistency = minLsnHeader
    ? { atLeastLsn: minLsnHeader, maxWaitMs: 250 }
    : ("replica" as const);
  try {
    const result = await engine.readStore.execute(consistency, fn, { timeoutMs });
    return result.data;
  } catch {
    return fn(primary);
  }
};

