  const paths: string[] = [];
  for (const spec of buildAllTopologySpecs()) {
    const path = configPathFor(spec.id, directory);
    writeFileSync(path, renderEnv(spec.buildEnv(lab)), { mode: 0o600 });
    paths.push(path);
  }
  return paths;
};

