   [
     `curl -fsS --max-time ${input.timeoutSeconds ?? 10}`,
     `--cacert ${input.certs}/internal-ca.crt`,
     `--cert ${input.certs}/${input.certName}.crt`,
     `--key ${input.certs}/${input.certName}.key`,
     input.url,
