   "-p", String(target.port),
   "-o", "BatchMode=yes",
   "-o", "StrictHostKeyChecking=accept-new",
   "-o", "ServerAliveInterval=20",
   "-o", "ServerAliveCountMax=6",
   `${target.user}@${target.host}`,
