 export const backupDaemonSystemdUnit = (config: DeployConfig): string => `[Unit]
 Description=Payment Gateway pg-backup-daemon (WAL-G / Barman control plane)
 After=network-online.target
 Wants=network-online.target

 [Service]
 Type=simple
