 Restart=always
 RestartSec=3
 LimitNOFILE=65536
 NoNewPrivileges=true
 ProtectSystem=strict
 ReadWritePaths=${[
   "/var/lib/pg-backup",
   "/var/log/pg-backup",
   dirname(config.BACKUP_CATALOG_PATH),
   config.BACKUP_DAEMON_CERT_DIR,
